<?php require 'bootstrap.php'; if(me()){header('Location: dashboard.php');exit;} $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$db->prepare('SELECT u.*,c.status church_status FROM users u LEFT JOIN churches c ON c.id=u.church_id WHERE u.email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&$u['active']&&password_verify($_POST['password']??'',$u['password_hash'])){if($u['role']!=='superadmin'&&$u['church_status']!=='approved')$error='Tu iglesia aún no está autorizada.';else{session_regenerate_id(true);$_SESSION['auth_signature']=hash('sha256',$u['password_hash']);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role'],'church_id'=>$u['church_id']];header('Location: dashboard.php');exit;}}else $error='Credenciales incorrectas.';}
?>
